### HTTP 安全标头 (Nginx)

```nginx
server {
    # 强制 1 年 + 子域 + 预加载
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains; preload" 始终;

    # 防止 MIME 嗅探
    add_header X-Content-Type-Options "nosniff" 始终;

    # 点击劫持保护
    add_header X-Frame-Options "DENY" 始终;

    # 推荐人政策
    add_header Referrer-Policy "strict-origin-when-cross-origin" 始终;

    # 禁用不必要的浏览器功能
    add_header Permissions-Policy "camera=(), microphone=(), geolocation=(), payment=()" 始终;

    # CSP — 调整脚本/样式源以匹配您的 CDN
    add_header Content-Security-Policy "default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; font-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'none';" 始终;

    # No-cache 用于身份验证路由
    location /api/auth/ {
        add_header Cache-Control "no-store" 始终;
    }

    # 删除服务器版本
    server_tokens off;
}
```

### CORS — 受限配置

```typescript
// Express + cors 包——显式白名单
import cors from "cors";

const corsOptions: cors.CorsOptions = {
  origin: (origin, callback) => {
    // 允许无来源的请求（服务器-to-server、curl、移动）
    if (!origin) return callback(null, true);

    if (config.allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error(`CORS: origin '${origin}' not allowed`));
    }
  },
  credentials: true,              // required for cookies
  methods: ["GET", "POST", "PUT", "DELETE", "OPTIONS"],
  allowedHeaders: ["Content-Type", "Authorization"],
};

app.use(cors(corsOptions));
```

### 速率限制（快速）

```typescript
import rateLimit from "express-rate-limit";

// Auth 路由 — 严格限制
export const authRateLimit = rateLimit({
  windowMs: 60 * 1000,             // 1 minute
  max: 30,                          // 30 requests per IP
  standardHeaders: true,            // X-RateLimit-* headers
  legacyHeaders: false,
  message: { error: "Too many requests. Please try again later." },
  skipSuccessfulRequests: false,
});

// 密码重置 — 非常严格
export const passwordResetLimit = rateLimit({
  windowMs: 15 * 60 * 1000,        // 15 minutes
  max: 5,
  message: { error: "Too many password reset attempts." },
});

// 通用 API — 经过身份验证后的每个用户
export const apiRateLimit = rateLimit({
  windowMs: 60 * 1000,
  max: 100,
  keyGenerator: (req) => req.user?.id || req.ip,
});

// 申请
app.use("/api/auth/login",          authRateLimit);
app.use("/api/auth/register",       authRateLimit);
app.use("/api/auth/reset-password", passwordResetLimit);
app.use("/api/",                    apiRateLimit);
```

### 输入验证（Zod — TypeScript）

```typescript
import { z } from "zod";

// 严格模式——拒绝任何未明确允许的内容
const CreateUserSchema = z.object({
  username: z.string()
    .min(3).max(30)
    .regex(/^[a-zA-Z0-9_-]+$/, "Only alphanumeric, underscore, hyphen"),
  email: z.string().email().max(254),
  role: z.enum(["user", "moderator"]),   // explicit allowlist — 绝不 'admin' from user input
});

// 中间件
export function validate<T>(schema: z.ZodSchema<T>) {
  return (req: Request, res: Response, next: NextFunction) => {
    const result = schema.safeParse(req.body);
    if (!result.success) {
      return res.status(400).json({
        error: "Validation failed",
        details: result.error.flatten().fieldErrors,
      });
    }
    req.body = result.data;  // replace with validated + typed data
    next();
  };
}

app.post("/api/users", validate(CreateUserSchema), createUserHandler);
```

