      <button
        onClick={() => trackEvent('hero_cta_click', { variant: heroVariant })}
        className="bg-blue-600 text-white px-8 py-3 rounded-lg text-lg hover:bg-blue-700"
      >
        {heroVariant}
      </button>
    </section>
  );
}
