        vault.withdraw();
    }

    function test_withdraw_succeedsAfterLock() public {
        vm.prank(alice);
        vault.stake(STAKE_AMOUNT);

        vm.warp(block.timestamp + LOCK_DURATION + 1);

        vm.prank(alice);
        vault.withdraw();

        (uint128 amount,,) = vault.stakes(alice);
        assertEq(amount, 0);
        assertEq(token.balanceOf(alice), 10_000e18);
