### Gas优化模式

```solidity
// SPDX 许可证标识符：MIT
pragma solidity ^0.8.24;

/// @title GasOptimizationPatterns
/// @notice 最小化 Gas 消耗的参考模式
contract GasOptimizationPatterns {
    // 模式 1：存储打包 — 在一个 32 字节槽中容纳多个值
    // 坏：3 个插槽（96 字节）
    // uint256 id；      // 槽0
    // uint256 金额；  // 槽1
    // 地址所有者；   // 槽2

    // 好：2 个插槽（64 字节）
    struct PackedData {
        uint128 id;       // slot 0 (16 bytes)
        uint128 amount;   // slot 0 (16 bytes) — same slot!
        address owner;    // slot 1 (20 bytes)
        uint96 timestamp; // slot 1 (12 bytes) — same slot!
    }

    // 模式 2：与需要字符串相比，自定义错误每次恢复可节省约 50 个 Gas
    error Unauthorized(address caller);
    error InsufficientBalance(uint256 requested, uint256 available);

    // 模式 3：使用数组上的映射进行查找 — O(1) 与 O(n)
    mapping(address => uint256) public balances;

    // 模式 4：缓存存储在内存中读取
    function optimizedTransfer(address to, uint256 amount) external {
        uint256 senderBalance = balances[msg.sender]; // 1 SLOAD
        if (senderBalance < amount) {
            revert InsufficientBalance(amount, senderBalance);
        }
        unchecked {
            // 通过上述检查，安全
            balances[msg.sender] = senderBalance - amount;
        }
        balances[to] += amount;
    }

    // 模式 5：使用 calldata 作为外部总线参数
    function processIds(uint256[] calldata ids) external pure returns (uint256 sum) {
        uint256 len = ids.length; // Cache length
        for (uint256 i; i < len;) {
            sum += ids[i];
            unchecked { ++i; } // Save gas on increment — cannot overflow
        }
    }

    // 模式 6：首选 uint256 / int256 — EVM 在 32 字节字上运行
    // 较小的类型（uint8、uint16）需要额外的气体来进行掩蔽，除非包装在存储中
}
