### 服务器权威玩家控制器

```csharp
public class PlayerController : NetworkBehaviour
{
    [SerializeField] private float _moveSpeed = 5f;
    [SerializeField] private float _reconciliationThreshold = 0.5f;

    // 服务器拥有权威地位
    private NetworkVariable<Vector3> _serverPosition = new NetworkVariable<Vector3>(
        readPerm: NetworkVariableReadPermission.Everyone,
        writePerm: NetworkVariableWritePermission.Server);

    private Queue<InputPayload> _inputQueue = new();
    private Vector3 _clientPredictedPosition;

    public override void OnNetworkSpawn()
    {
        if (!IsOwner) return;
        _clientPredictedPosition = transform.position;
    }

    private void Update()
    {
        if (!IsOwner) return;

        // 本地读取输入
        var input = new Vector2(Input.GetAxisRaw("Horizontal"), Input.GetAxisRaw("Vertical")).normalized;

        // 客户预测：立即行动
        _clientPredictedPosition += new Vector3(input.x, 0, input.y) * _moveSpeed * Time.deltaTime;
        transform.position = _clientPredictedPosition;

        // 将输入发送到服务器
        SendInputServerRpc(input, NetworkManager.LocalTime.Tick);
    }

    [ServerRpc]
    private void SendInputServerRpc(Vector2 input, int tick)
    {
        // 服务器模拟此输入的移动
        Vector3 newPosition = _serverPosition.Value + new Vector3(input.x, 0, input.y) * _moveSpeed * Time.fixedDeltaTime;

        // 服务器验证：这在物理上可行吗？ （反作弊）
        float maxDistancePossible = _moveSpeed * Time.fixedDeltaTime * 2f; // 2x tolerance for lag
        if (Vector3.Distance(_serverPosition.Value, newPosition) > maxDistancePossible)
        {
            // 拒绝：传送尝试或严重不同步
            _serverPosition.Value = _serverPosition.Value; // Force reconciliation
            return;
        }

        _serverPosition.Value = newPosition;
    }

    private void LateUpdate()
    {
        if (!IsOwner) return;

        // 协调：如果客户端距离服务器较远，则快速返回
        if (Vector3.Distance(transform.position, _serverPosition.Value) > _reconciliationThreshold)
        {
            _clientPredictedPosition = _serverPosition.Value;
            transform.position = _clientPredictedPosition;
        }
    }
}
```

